macro_rules! test_cleanup_semantic {
    () => {
        # [test] fn test_cleanup_semantic () { let mut solution = diff_list ! [] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([] , solution , "Null case") ; let mut solution = diff_list ! [Delete ("ab") , Insert ("cd") , Equal ("12") , Delete ("e")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("ab") , Insert ("cd") , Equal ("12") , Delete ("e")] , solution , "No elimination #1" ,) ; let mut solution = diff_list ! [Delete ("abc") , Insert ("ABC") , Equal ("1234") , Delete ("wxyz")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("abc") , Insert ("ABC") , Equal ("1234") , Delete ("wxyz")] , solution , "No elimination #2" ,) ; let mut solution = diff_list ! [Delete ("a") , Equal ("b") , Delete ("c")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("abc") , Insert ("b")] , solution , "Simple elimination" ,) ; let mut solution = diff_list ! [Delete ("ab") , Equal ("cd") , Delete ("e") , Equal ("f") , Insert ("g") ,] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("abcdef") , Insert ("cdfg")] , solution , "Backpass elimination" ,) ; let mut solution = diff_list ! [Insert ("1") , Equal ("A") , Delete ("B") , Insert ("2") , Equal ("_") , Insert ("1") , Equal ("A") , Delete ("B") , Insert ("2") ,] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("AB_AB") , Insert ("1A2_1A2")] , solution , "Multiple elimination" ,) ; let mut solution = diff_list ! [Equal ("The c") , Delete ("ow and the c") , Equal ("at.")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Equal ("The ") , Delete ("cow and the ") , Equal ("cat.")] , solution , "Word boundaries" ,) ; let mut solution = diff_list ! [Delete ("abcxx") , Insert ("xxdef")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("abcxx") , Insert ("xxdef")] , solution , "No overlap elimination" ,) ; let mut solution = diff_list ! [Delete ("abcxxx") , Insert ("xxxdef")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("abc") , Equal ("xxx") , Insert ("def")] , solution , "Overlap elimination" ,) ; let mut solution = diff_list ! [Delete ("xxxabc") , Insert ("defxxx")] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Insert ("def") , Equal ("xxx") , Delete ("abc")] , solution , "Reverse overlap elimination" ,) ; let mut solution = diff_list ! [Delete ("abcd1212") , Insert ("1212efghi") , Equal ("----") , Delete ("A3") , Insert ("3BC") ,] ; cleanup_semantic (& mut solution) ; assert_diffs ! ([Delete ("abcd") , Equal ("1212") , Insert ("efghi") , Equal ("----") , Delete ("A") , Equal ("3") , Insert ("BC") ,] , solution , "Two overlap eliminations" ,) ; }
    };
}

test_cleanup_semantic!();